// Extract telemetry fields from incoming POST body
var data = msg.payload;

// Validate required fields
var temperature = parseFloat(data.temperature) || 0;
var current = parseFloat(data.current) || 0;
var vibration = parseFloat(data.vibration) || 0;
var rpm = parseFloat(data.rpm) || 0;
var battery = parseFloat(data.battery) || 100;
var fused_prob = parseFloat(data.fused_prob) || 0;
var cnn_prob = parseFloat(data.cnn_prob) || 0;
var rf_prob = parseFloat(data.rf_prob) || 0;
var timestamp = data.timestamp || new Date().toISOString();

// Build clean telemetry object
msg.telemetry = {
    temperature: temperature,
    current: current,
    vibration: vibration,
    rpm: rpm,
    battery: battery,
    fused_prob: fused_prob,
    cnn_prob: cnn_prob,
    rf_prob: rf_prob,
    timestamp: timestamp
};

// Determine machine status
var FAULT_THRESHOLD = 0.5;
msg.telemetry.is_faulty = fused_prob >= FAULT_THRESHOLD;
msg.telemetry.status = msg.telemetry.is_faulty ? 'FAULTY' : 'HEALTHY';

// Set status display on node
node.status({
    fill: msg.telemetry.is_faulty ? 'red' : 'green',
    shape: 'dot',
    text: msg.telemetry.status + ' | T:' + temperature.toFixed(1) + '°C | I:' + current.toFixed(2) + 'A'
});

return msg;

// Format telemetry as InfluxDB line protocol compatible payload
var t = msg.telemetry;

msg.payload = [
    {
        measurement: 'machine_telemetry',
        tags: {
            machine_id: 'esp32_node_01',
            status: t.status
        },
        fields: {
            temperature: t.temperature,
            current: t.current,
            vibration: t.vibration,
            rpm: t.rpm,
            battery: t.battery,
            fused_prob: t.fused_prob,
            cnn_prob: t.cnn_prob,
            rf_prob: t.rf_prob
        },
        timestamp: new Date()
    }
];

return msg;

// Only send to Back4App if a fault condition is detected
var t = msg.telemetry;
var alerts = [];

// Rule 1: High fused fault probability
if (t.fused_prob >= 0.5) {
    alerts.push({
        eventType: 'FAULT_DETECTED',
        severity: t.fused_prob >= 0.8 ? 'CRITICAL' : 'WARNING',
        description: 'Fused AI model detected fault (prob: ' + (t.fused_prob * 100).toFixed(1) + '%)',
        fusedProb: t.fused_prob,
        cnnProb: t.cnn_prob,
        rfProb: t.rf_prob
    });
}

// Rule 2: Temperature threshold breach
if (t.temperature > 45.0) {
    alerts.push({
        eventType: 'TEMPERATURE_ALERT',
        severity: t.temperature > 60.0 ? 'CRITICAL' : 'WARNING',
        description: 'Temperature exceeded threshold: ' + t.temperature.toFixed(1) + '°C',
        temperature: t.temperature
    });
}

// Rule 3: Overcurrent
if (t.current > 3.0) {
    alerts.push({
        eventType: 'OVERCURRENT_ALERT',
        severity: t.current > 5.0 ? 'CRITICAL' : 'WARNING',
        description: 'Current exceeded threshold: ' + t.current.toFixed(2) + 'A',
        current: t.current
    });
}

// Rule 4: Low battery
if (t.battery < 10.0 && t.battery > 0) {
    alerts.push({
        eventType: 'LOW_BATTERY',
        severity: 'WARNING',
        description: 'Battery critically low: ' + t.battery.toFixed(1) + '%',
        battery: t.battery
    });
}

// Only proceed if there are alerts
if (alerts.length > 0) {
    msg.alerts = alerts;
    node.status({fill: 'red', shape: 'ring', text: alerts.length + ' alert(s) detected'});
    return msg;
} else {
    node.status({fill: 'green', shape: 'dot', text: 'No faults'});
    return null;  // Do not send downstream
}

// Send each alert as a separate Back4App MachineEvent object
// Process alerts sequentially
var alerts = msg.alerts || [];
var messages = [];

for (var i = 0; i < alerts.length; i++) {
    var alert = alerts[i];
    var newMsg = {
        payload: JSON.stringify({
            eventType: alert.eventType,
            severity: alert.severity,
            description: alert.description,
            machineId: 'esp32_node_01',
            telemetry: {
                temperature: msg.telemetry.temperature,
                current: msg.telemetry.current,
                vibration: msg.telemetry.vibration,
                rpm: msg.telemetry.rpm,
                battery: msg.telemetry.battery
            },
            aiPredictions: {
                fusedProb: msg.telemetry.fused_prob,
                cnnProb: msg.telemetry.cnn_prob,
                rfProb: msg.telemetry.rf_prob
            },
            resolvedAt: null
        }),
        headers: {
            'X-Parse-Application-Id': global.get('back4app_app_id') || env.get('BACK4APP_APP_ID') || '',
            'X-Parse-REST-API-Key': global.get('back4app_rest_key') || env.get('BACK4APP_REST_KEY') || '',
            'Content-Type': 'application/json'
        }
    };
    messages.push(newMsg);
}

// Send first alert (Node-RED processes one at a time)
if (messages.length > 0) {
    node.status({fill: 'yellow', shape: 'dot', text: 'Sending ' + messages.length + ' event(s) to Back4App'});
    return messages[0];
}
return null;

// Rate limit ThingSpeak to 15-second intervals
var lastSend = flow.get('thingspeak_last_send') || 0;
var now = Date.now();

if (now - lastSend < 15000) {
    node.status({fill: 'grey', shape: 'ring', text: 'Rate limited'});
    return null;  // Skip this update
}

flow.set('thingspeak_last_send', now);

var t = msg.telemetry;
var apiKey = global.get('thingspeak_write_key') || env.get('THINGSPEAK_WRITE_KEY') || '';

if (!apiKey) {
    node.status({fill: 'grey', shape: 'dot', text: 'No API key configured'});
    return null;
}

// ThingSpeak update URL with query parameters
var params = 'api_key=' + apiKey +
    '&field1=' + t.temperature.toFixed(2) +
    '&field2=' + t.current.toFixed(2) +
    '&field3=' + t.vibration.toFixed(4) +
    '&field4=' + t.rpm.toFixed(1) +
    '&field5=' + t.battery.toFixed(1) +
    '&field6=' + (t.fused_prob * 100).toFixed(1) +
    '&field7=' + (t.cnn_prob * 100).toFixed(1) +
    '&field8=' + (t.rf_prob * 100).toFixed(1);

msg.url = 'https://api.thingspeak.com/update?' + params;
msg.payload = '';

node.status({fill: 'blue', shape: 'dot', text: 'Sending to ThingSpeak'});
return msg;

var data = msg.payload;

msg.payload = JSON.stringify({
    eventType: data.alert_type || 'MANUAL_ALERT',
    severity: data.severity || 'INFO',
    description: data.message || 'Manual alert from dashboard',
    machineId: 'esp32_node_01',
    source: 'dashboard_manual',
    resolvedAt: null
});

msg.headers = {
    'X-Parse-Application-Id': global.get('back4app_app_id') || env.get('BACK4APP_APP_ID') || '',
    'X-Parse-REST-API-Key': global.get('back4app_rest_key') || env.get('BACK4APP_REST_KEY') || '',
    'Content-Type': 'application/json'
};

node.status({fill: 'yellow', shape: 'dot', text: 'Manual alert: ' + (data.alert_type || 'MANUAL')});

return msg;
